/**
 * The client's own card for a door that led to a web page, not a world
 * (src/veml/webPage.ts): it names the page's host, offers a link to that
 * very address for the visitor to open in a new tab with their own click,
 * and a way to stay in the world they are in, which a failed load never
 * left. Nothing here opens anything by itself. Loaded only when a door
 * leads to a web page.
 */

export const WEB_PAGE_CARD_ID = 'webverse-web-page';
export const WEB_PAGE_WORDS = {
  isWebPage: (host: string) => `${host} is a web page, not a place.`,
  openInNewTab: 'Open it in a new tab',
  stay: 'Stay here',
} as const;

/** Shows the card for the web page at `url`; `onStay` is the visitor choosing to stay where they are. */
export function showWebPageCard(doc: Document, url: string, onStay: () => void): void {
  doc.getElementById(WEB_PAGE_CARD_ID)?.remove();
  let at: URL | null = null;
  try {
    // An address on the page's own site may come without its host.
    at = new URL(url, doc.baseURI);
  } catch {
    // Not an address: the card names nothing to open.
  }
  const card = doc.createElement('div');
  card.id = WEB_PAGE_CARD_ID;
  card.setAttribute('role', 'status');
  card.style.cssText =
    'position:fixed;left:50%;top:20px;transform:translateX(-50%);z-index:20;display:flex;flex-wrap:wrap;align-items:center;' +
    'gap:10px 14px;max-width:calc(100% - 48px);padding:14px 18px;border-radius:12px;background:rgba(20,20,24,.92);' +
    'color:#fff;font:15px/1.4 system-ui,sans-serif;box-shadow:0 8px 30px rgba(0,0,0,.5)';
  const line = doc.createElement('p');
  line.style.cssText = 'margin:0;flex:1 1 100%';
  line.textContent = WEB_PAGE_WORDS.isWebPage(at?.host ?? '');
  card.appendChild(line);
  if (at !== null && (at.protocol === 'https:' || at.protocol === 'http:')) {
    const link = doc.createElement('a');
    link.href = at.href;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.textContent = WEB_PAGE_WORDS.openInNewTab;
    link.style.cssText = 'color:#c7d2fe;font-weight:600';
    card.appendChild(link);
  }
  const stay = doc.createElement('button');
  stay.type = 'button';
  stay.textContent = WEB_PAGE_WORDS.stay;
  stay.style.cssText = 'font:inherit;color:#fff;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.35);border-radius:6px;padding:6px 12px;cursor:pointer';
  stay.addEventListener('click', () => {
    card.remove();
    onStay();
  });
  card.appendChild(stay);
  doc.body.appendChild(card);
}
